class TreeNode:
    def __init__(self, v):
        self.v = v
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, v):
        def rec(n):
            if n is None:
                return TreeNode(v)
            if v < n.v:
                n.left = rec(n.left)
            else:
                n.right = rec(n.right)
            return n
        self.root = rec(self.root)

    def in_order(self):
        out = []
        def rec(n):
            if n:
                rec(n.left)
                out.append(n.v)
                rec(n.right)
        rec(self.root)
        return out

    def height(self):
        def h(n):
            return -1 if n is None else 1 + max(h(n.left), h(n.right))
        return h(self.root)

